components.css:
.ds-guide {
  position: relative;
  top: auto;
  left: auto;
  display: flex;
  flex-direction: column;
  width: 360px;
  max-width: calc(100% - 24px);
  max-height: 420px;
  padding: 18px;
  border-radius: 14px;
  background: var(--card);
  color: var(--foreground);
  box-shadow: 0 14px 36px rgb(0 0 0 / 20%);
  pointer-events: auto;
}
.ds-guide-copy {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}
.ds-guide-copy h2 {
  flex: 0 0 auto;
  margin: 0;
  font-size: 18px;
  font-weight: 650;
  line-height: 1.4;
  letter-spacing: -.015em;
  text-wrap: balance;
}
.ds-guide-copy p {
  flex: 1 1 auto;
  min-height: 0;
  margin: 8px 0 0;
  overflow-y: auto;
  font-size: 14px;
  line-height: 1.6;
  color: var(--muted-foreground);
  text-wrap: pretty;
  scrollbar-color: var(--muted-foreground) var(--card);
  scrollbar-width: thin;
}
.ds-guide-progress {
  display: flex;
  flex: 0 0 auto;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.5;
  color: var(--muted-foreground);
}
.ds-guide-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 10px;
}
.ds-guide button:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
.ds-guide-error {
  flex: 0 0 auto;
  margin: 10px 0 0;
  font-size: 12px;
  line-height: 1.6;
  color: var(--destructive);
}

.ds-guide{font-family:ui-sans-serif,system-ui,sans-serif}.ds-guide-actions>div{display:flex;flex-wrap:wrap;gap:8px}.ds-guide-actions button{min-height:44px;padding:0 10px;border:1px solid transparent;border-radius:var(--radius-md,8px);font-family:inherit;font-size:14px;font-weight:500;line-height:20px;cursor:pointer}.ds-guide-actions button:disabled{pointer-events:none;opacity:.5}.ds-guide-skip{background:transparent;color:var(--foreground,#22211f)}.ds-guide-skip:hover{background:var(--muted,#e7e6e2)}.ds-guide-back{border-color:var(--border,#d4d2cc)!important;background:var(--background,#f0f0ee);color:var(--foreground,#22211f)}.ds-guide-back:hover{background:var(--muted,#e7e6e2)}.ds-guide-next{background:var(--primary,#22211f);color:var(--primary-foreground,#f0f0ee)}.ds-guide-next:hover{background:color-mix(in srgb,var(--primary,#22211f) 80%,transparent)}
